#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "clip_hierarchy.h"
#include "channel_binding.h"
#include "session_runtime.h"
#include "runtime_typed_channel_copy.h"
int main(int argc,char**argv){try{if(argc!=2)return 1;SessionRuntime owned(loadGraph(argv[1]));auto&g=owned.graph;unsigned checks=0,vectorChecks=0,quaternionChecks=0;for(uint32_t id=0;id<g.elements.size();++id){if(g.strings[g.elements[id].type]!="DmeChannel")continue;ChannelBinding b(g,id);auto type=b.destination.scalarType;if(!b.source.present()||!b.destination.present()||type!=b.source.scalarType||(type!=10&&type!=13))continue;if(b.source.element==b.destination.element&&b.source.attribute==b.destination.attribute)continue;setWireU32(runtimeAttribute(g,id,"mode")->values[0],1);RuntimeCachedTypedCopyBinding live(g,id,owned.elements,owned.attributes);auto*s=runtimeAttribute(g,b.source.element,b.source.attribute);auto*d=runtimeAttribute(g,b.destination.element,b.destination.attribute);unsigned components=type==10?3:4;for(unsigned c=0;c<components;++c){setFloat(*s,b.source.index,float(c)+.125f,c);setFloat(*d,b.destination.index,12345.f,c);}auto expected=s->values[b.source.index].wire;SessionAttributeChanges changes;if(!executeRuntimeTypedCopy(g,owned.elements,owned.attributes,live,&changes)||changes.attributes.size()!=1||d->values[b.destination.index].wire!=expected)throw std::runtime_error("typed copy mismatch");changes.attributes.clear();if(!executeRuntimeTypedCopy(g,owned.elements,owned.attributes,live,&changes)||!changes.attributes.empty())throw std::runtime_error("unchanged copy mismatch");++checks;if(type==10)++vectorChecks;else ++quaternionChecks;}if(!checks)throw std::runtime_error("no typed copies exercised");std::cout<<"typed_copy_channels="<<checks<<" vectors="<<vectorChecks<<" quaternions="<<quaternionChecks<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
